// Extract function signatures, TODO/FIXME/BUG comments, and error handling
const fs = require('fs');
const content = fs.readFileSync(process.argv[0], 'utf8');

const lines = content.split('\n');
const issues = [];
const functions = [];

lines.forEach((line, idx) => {
  // Capture TODOs, FIXMEs, BUGs
  if (/TODO|FIXME|BUG|XXX|HACK/i.test(line)) {
    issues.push(`Line ${idx + 1}: ${line.trim()}`);
  }
  // Capture function definitions
  if (/^(async\s+)?function\s+\w+|const\s+\w+\s*=\s*(async\s*)?\(/. test(line)) {
    functions.push(line.trim().substring(0, 80));
  }
});

console.log('=== FUNCTIONS ===');
functions.slice(0, 10).forEach(f => console.log(f));
console.log('\n=== ISSUES (TODO/FIXME/BUG) ===');
if (issues.length === 0) {
  console.log('(none found)');
} else {
  issues.forEach(issue => console.log(issue));
}
console.log('\n=== FILE SIZE & SCOPE ===');
console.log('Lines:', lines.length, '| Size:', (content.length / 1024).toFixed(1), 'KB');
